func expandPubsubSnapshotSubscription(v interface{}, d tpgresource.TerraformResourceData, config *transport_tpg.Config) (interface{}, error) {
	project, err := tpgresource.GetProject(d, config)
	if err != nil {
		return "", err
	}

	subscription := d.Get("subscription").(string)

	re := regexp.MustCompile(`projects\/(.*)\/subscriptions\/(.*)`)
	match := re.FindStringSubmatch(subscription)
	if len(match) == 3 {
		return subscription, nil
	} else {
		// If no full subscription given, we expand it to a full subscription on the same project
		fullSub := fmt.Sprintf("projects/%s/subscriptions/%s", project, subscription)
		if err := d.Set("subscription", fullSub); err != nil {
			return nil, fmt.Errorf("Error setting subscription: %s", err)
		}
		return fullSub, nil
	}
}

